@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap');

    :root {
      color-scheme: dark light;

      --bg: oklch(0.11 0.02 260);
      --bg-soft: oklch(0.14 0.02 260);
      --card: oklch(0.18 0.02 260 / .55);
      --line: oklch(1 0 0 / .08);
      --text: oklch(0.96 0.01 250);
      --muted: oklch(0.72 0.02 250);

      --accent: oklch(0.78 0.19 240);
      --accent-2: oklch(0.74 0.16 190);

      --mouse-x: 50%;
      --mouse-y: 50%;
    }.sc-tw [data-theme="light"]{
      --bg: oklch(0.97 0.01 250);
      --bg-soft: oklch(0.94 0.01 250);
      --card: oklch(1 0 0 / .52);
      --line: oklch(0 0 0 / .06);
      --text: oklch(0.18 0.02 260);
      --muted: oklch(0.42 0.02 260);

      --accent: oklch(0.63 0.22 250);
      --accent-2: oklch(0.70 0.16 200);
    }.sc-tw *{
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }.sc-tw html{
      scroll-behavior: smooth;
    }.sc-tw{
      font-family: 'Inter', sans-serif;
      background: var(--bg);
      color: var(--text);
      overflow-x: hidden;
      letter-spacing: -0.02em;
    }.sc-tw body::before{
      content: "";
      position: fixed;
      inset: 0;
      pointer-events: none;
      background:
        radial-gradient(circle at top left, color-mix(in oklch, var(--accent) 16%, transparent), transparent 32%),
        radial-gradient(circle at bottom right, color-mix(in oklch, var(--accent-2) 12%, transparent), transparent 28%);
      opacity: .9;
      z-index: -2;
    }.sc-tw .noise::before{
      content: "";
      position: absolute;
      inset: 0;
      opacity: .04;
      background-image:
        radial-gradient(circle at center, white 1px, transparent 1px);
      background-size: 18px 18px;
      pointer-events: none;
    }.sc-tw .liquid-shell{
      position: relative;
      background:
        linear-gradient(180deg,
          color-mix(in oklch, var(--card) 95%, transparent),
          color-mix(in oklch, var(--bg-soft) 88%, transparent));

      border: 1px solid var(--line);

      box-shadow:
        0 2px 6px rgba(0, 0, 0, .08),
        0 20px 80px rgba(0, 0, 0, .35),
        inset 0 1px 0 rgba(255, 255, 255, .08),
        inset 0 -1px 0 rgba(255, 255, 255, .02);

      backdrop-filter: blur(24px) saturate(190%);
      -webkit-backdrop-filter: blur(24px) saturate(190%);
    }.sc-tw .hero-grid{
      container-type: inline-size;
    }.sc-tw .kinetic-title{
      font-size: clamp(4rem, 11vw, 10rem);
      line-height: .82;
      letter-spacing: -0.08em;
      font-weight: 900;

      background:
        linear-gradient(130deg,
          rgba(255, 255, 255, 1),
          rgba(255, 255, 255, .55),
          rgba(255, 255, 255, 1));

      background-size: 220% auto;
      color: transparent;
      -webkit-background-clip: text;

      animation: shimmer 7s linear infinite;
    }

    @keyframes shimmer {from{
        background-position: 0% center;
      }to{
        background-position: 220% center;
      }
    }.sc-tw .hero-description{
      color: var(--muted);
      font-size: 1rem;
      line-height: 1.8;
      max-width: 34rem;
    }.sc-tw .video-portal{
      position: absolute;
      top: 7%;
      right: -10%;
      width: min(60vw, 980px);
      height: 88%;
      overflow: hidden;
      border-radius: 4rem;

      transform:
        perspective(1800px) rotateY(-10deg) rotateX(3deg);

      isolation: isolate;
    }.sc-tw .video-portal::before{
      content: "";
      position: absolute;
      inset: -1px;
      border-radius: inherit;
      padding: 1px;

      background:
        linear-gradient(130deg,
          rgba(255, 255, 255, .45),
          rgba(255, 255, 255, .02),
          rgba(255, 255, 255, .25));

      -webkit-mask:
        linear-gradient(#000 0 0) content-box,
        linear-gradient(#000 0 0);

      -webkit-mask-composite: xor;
      mask-composite: exclude;
      pointer-events: none;
      z-index: 5;
    }.sc-tw .video-portal video{
      width: 100%;
      height: 100%;
      object-fit: cover;

      filter:
        saturate(120%) contrast(112%) brightness(.92);

      mask-image:
        radial-gradient(circle at var(--mouse-x) var(--mouse-y),
          black 25%,
          rgba(0, 0, 0, .92) 45%,
          transparent 85%);

      -webkit-mask-image:
        radial-gradient(circle at var(--mouse-x) var(--mouse-y),
          black 25%,
          rgba(0, 0, 0, .92) 45%,
          transparent 85%);
    }.sc-tw .video-glow{
      position: absolute;
      inset: 0;
      background:
        radial-gradient(circle at var(--mouse-x) var(--mouse-y),
          color-mix(in oklch, var(--accent) 35%, transparent),
          transparent 55%);
      mix-blend-mode: screen;
      opacity: .65;
      pointer-events: none;
    }.sc-tw .glass-intersection{
      position: absolute;
      left: 0;
      bottom: 0;
      width: 50%;
      height: 45%;

      background:
        linear-gradient(180deg,
          rgba(255, 255, 255, .04),
          rgba(255, 255, 255, .02));


      mask-image:
        linear-gradient(to top, black 75%, transparent 100%);

      border-top: 1px solid rgba(255, 255, 255, .08);
      border-right: 1px solid rgba(255, 255, 255, .05);

      pointer-events: none;
    }.sc-tw .liquid-btn{
      position: relative;
      isolation: isolate;
      overflow: hidden;

      border-radius: 999px;
      padding: 1rem 1.4rem;

      background:
        linear-gradient(130deg,
          rgba(255, 255, 255, .12),
          rgba(255, 255, 255, .03));

      border: 1px solid rgba(255, 255, 255, .1);

      box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, .12),
        0 14px 40px rgba(0, 0, 0, .24);

      transition:
        transform .45s cubic-bezier(.16, 1, .3, 1),
        border-color .4s ease;
    }.sc-tw .liquid-btn::before{
      content: "";
      position: absolute;
      inset: -40%;

      background:
        radial-gradient(circle at var(--mouse-x) var(--mouse-y),
          rgba(255, 255, 255, .75),
          rgba(255, 255, 255, .14) 18%,
          transparent 48%);

      opacity: .9;
      transition: transform .12s linear;
      z-index: -1;
    }.sc-tw .liquid-btn:hover{
      transform: translateY(-5px) scale(1.01);
      border-color: rgba(255, 255, 255, .25);
    }.sc-tw .bento{
      display: grid;
      grid-template-columns: repeat(12, 1fr);
      gap: 1.2rem;
    }.sc-tw .bento-card{
      position: relative;
      overflow: hidden;
      border-radius: 2rem;
      min-height: 260px;
      padding: 2rem;

      background:
        linear-gradient(180deg,
          rgba(255, 255, 255, .06),
          rgba(255, 255, 255, .02));

      border: 1px solid rgba(255, 255, 255, .08);

      backdrop-filter: blur(24px);

      box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, .08),
        0 20px 60px rgba(0, 0, 0, .2);

      transition:
        transform .5s cubic-bezier(.16, 1, .3, 1),
        border-color .4s ease;
    }.sc-tw .bento-card::before{
      content: "";
      position: absolute;
      inset: 0;
      background:
        radial-gradient(400px circle at var(--mouse-x) var(--mouse-y),
          rgba(255, 255, 255, .12),
          transparent 40%);
      opacity: 0;
      transition: opacity .4s ease;
    }.sc-tw .bento-card:hover{
      transform: translateY(-10px);
      border-color: rgba(255, 255, 255, .18);
    }.sc-tw .bento-card:hover::before{
      opacity: 1;
    }.sc-tw .fade-edge{
      mask-image:
        linear-gradient(to right,
          transparent,
          black 10%,
          black 90%,
          transparent);
    }.sc-tw .scroll-fade{
      mask-image:
        linear-gradient(to bottom,
          transparent,
          black 12%,
          black 88%,
          transparent);
    }.sc-tw .section-reveal{
      opacity: .2;
      transform: translateY(80px) scale(.96);
      filter: blur(18px);

      animation:
        reveal linear forwards;

      animation-timeline: view();
      animation-range: entry 15% cover 40%;
    }

    @keyframes reveal {to{
        opacity: 1;
        transform: translateY(0) scale(1);
        filter: blur(0);
      }
    }.sc-tw .tiny-label{
      color: var(--muted);
      font-size: .78rem;
      text-transform: uppercase;
      letter-spacing: .28em;
    }.sc-tw .theme-switch{
      width: 54px;
      height: 32px;
      border-radius: 999px;
      position: relative;
      cursor: pointer;

      background: rgba(255, 255, 255, .08);
      border: 1px solid rgba(255, 255, 255, .08);
      backdrop-filter: blur(20px);
    }.sc-tw .theme-switch::before{
      content: "";
      position: absolute;
      width: 24px;
      height: 24px;
      border-radius: 999px;
      top: 3px;
      left: 3px;

      background: white;
      transition: .45s cubic-bezier(.16, 1, .3, 1);
    }.sc-tw [data-theme="light"] .theme-switch::before{
      left: 25px;
    }

    @container (max-width: 980px) {.sc-tw .video-portal{
        position: relative;
        inset: auto;
        width: 100%;
        height: 420px;
        margin-top: 4rem;

        transform: none;
      }.sc-tw .glass-intersection{
        width: 100%;
      }.sc-tw .hero-stack{
        flex-direction: column;
      }.sc-tw .bento{
        grid-template-columns: 1fr;
